    "vals": "Przebiegły Zamach: cięcie półkolem – 30 / 40 / 50 / 60 (+30% dod. AD) obrażeń fizycznych + 2% / 2.5% / 3% / 3.5% (+0.02% dod. AD) maks. zdrowia celu. Na krawędzi cięcia obrażenia rosną do 60 / 80 / 100 / 120 (+60% dod. AD) + 4% / 5% / 6% / 7% (+0.04% dod. AD) maks. zdrowia.\nTrafienie zamienia umiejętność na 3.5 s w Rozdzierające Uderzenie.\nRozdzierające Uderzenie: cięcie w linii – pierwszy trafiony wróg otrzymuje 70 / 100 / 130 / 160 (+90% dod. AD) obrażeń fizycznych + 4% / 5% / 6% / 7% (+0.04 dod. AD) maks. zdrowia, pozostali 35 / 50 / 65 / 80 (+45% dod. AD) + 2% / 2.5% / 3% / 3.5% (+0.02% dod. AD) maks. zdrowia.\nObrażenia % zdrowia przeciw potworom ograniczone do 55.",
