    "vals": "Umiejętności zadające obrażenia dają ładunki Gwiezdnego Pyłu, które wzmacniają umiejętności:\nOddech Światła: wybuchy zadają dodatkowo 0% (3% ładunków) maks. zdrowia celu.\nLot Astralny: maks. dystans lotu +0% (62.5% ładunków).\nOsobliwość: obszar +0% (40% ładunków), próg egzekucji +0% (2.1% ładunków).\nSpadająca Gwiazda / Niebiosa Zstępują: obszar +0% (40% ładunków)."
