    "vals": "Pierwsze użycie: lot w wybranym kierunku; w locie Oddech Światła nie ma odnowienia ani limitu czasu i zadaje 15% / 20% / 25% / 30% więcej obrażeń.\nPonowne użycie: wcześniejsze lądowanie.\nZabicie bohatera w ciągu 3 s od obrażeń zwraca 90% odnowienia.\nPrędkość lotu: 300 + 100 prędkości ruchu; zmniejszona o 50% podczas używania Oddechu.",
