    "vals": "Pierwsze użycie: pocisk przeklętej energii – 40 / 70 / 100 / 130 (+33% AP) obrażeń magicznych i klątwa na 3.5 s.\nPonowne użycie: klątwy wracają do Aurory, zadając do 40 / 70 / 100 / 130 (+33% AP) obrażeń magicznych wrogom na drodze; do 50% więcej zależnie od brakującego zdrowia.\nKolejne trafienia zadają 20% mniej. Przeciw stworom i potworom 40% obrażeń.\nPo wygaśnięciu klątwy umiejętność aktywuje się automatycznie.",
