    "vals": "Skok w wybranym kierunku; po lądowaniu Aurora wchodzi do świata duchów, jest niewidzialna przez 1 / 1.2 / 1.4 / 1.6 s i zyskuje Przeskok Między Światami.\nPrzeskok Między Światami: 25% / 30% / 35% / 40% prędkości ruchu na 4 s.\nZabójstwo/asysta na bohaterze resetuje odnowienie.",
