    "vals": "Szarża: 80 / 140 / 200 / 260 (+40% dod. pancerza +40% dod. odporności na magię) obrażeń fizycznych. Uderzenie w teren tworzy falę uderzeniową, która podrzuca wrogów na 1.25 s i zadaje im te same obrażenia.\nNiszczy filary i teren stworzony przez wrogów oraz skraca odnowienie o 25%.",
