    "vals": "Dusze bohaterów zmarłych w ciągu 3 s od obrażeń Viego stają się upiorami na 8 s. Kanałowanie 1 s pozwala je opętać na 10 s. W opętaniu:\n- nie można go obrać za cel,\n- darmowe użycie Łamacza Serc,\n- 10% prędkości ruchu w stronę wrogich bohaterów,\n- dostęp do podstawowych umiejętności, ataków i przedmiotów opętanego,\n- leczenie o 5% (2 + 4% dod. AD + 2% AP + 5 dod. prędkości ataku) maks. zdrowia celu.\nNie może używać aktywnych efektów zaklęć przedmiotów opętanego."
